------------------------------------------------------ public

function ActivityFashionPreheatingCell:Refresh(data, index)
    if not data or next(data) == nil then
        return
    end

    self:SetLuaIndex(index)
    self.taskData = data

    CfUtils.FillText(self.TxtTaskContent, tostring(data.desc))

    -- refresh progress
    self.ImgProgressBar.fillAmount = math.min(checkInt(data.progress) / checkInt(data.targetNum), 1)
    CfUtils.FillText(self.TxtNumber, string.format("(%s/%s)", tostring(math.min(checkInt(data.progress), checkInt(data.targetNum))), tostring(data.targetNum)))
    self:RefreshStatue()
    if isNull(self.GoodNode.Env) then
        self.GoodNode:Init()
    end
    ---@type GoodNodeMB
    local Env = self.GoodNode.Env
    local rewards =  self:GetTaskDt().rewards[1]
    Env:Reload({
        goodsId = rewards.goodsId,
        text = string.format("x%d", rewards.num),
        isShowNo = true
    })
    Env:SetClickButtonAction(function(goodsId, id)
        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
        if isTable(vo) then
            GameUtils.ShowCommonTipsBoard(self.GoodNode.gameObject, vo.name, vo.desc, vo.quality, vo.id)
        end
    end)
end

function ActivityFashionPreheatingCell:RefreshStatue()
    local isCan = self:GetStatus() == Constants.GetStatus.Can
    local isGot = self:GetStatus() == Constants.GetStatus.Has
    local isNot = self:GetStatus() == Constants.GetStatus.Not
    local isCanJump = isNot and self:GetOpenType() > 0
    if self.GoodNode.Env then
        self.GoodNode:Init()
    end

    -- refresh reward
    -- if isNull(self.CommonGoodsList.Env) then
    --     self.CommonGoodsList:Init()
    -- end
    --self.CommonGoodsList.Env:SetCanGetEffectShow(isCan)
    --self.CommonGoodsList.Env:SetIsGetMaskShow(isGot)
    KTool.SetActive(self.FontStyleButton, isCan or isCanJump)
    KTool.SetActive(self.TxtTaskIng, isNot and self:GetOpenType() <= 0)
    KTool.SetActive(self.ImgFinish, isGot)
    KTool.SetActive(self.Black, isGot)
    KTool.SetActive(self.CanAnim, isCan)
    CfUtils.SetUISwitchImage(self.ImgFrame2, isCan and 1 or 2)
    CfUtils.SetUISwitchImage(self.ImgFrame, isCan and 1 or 2)

    -- refresh btn
    if not isGot then
        if isCan then
            self.FontStyleButton:ResetFontStyle("B12", localize("领取"))
        elseif isCanJump then
            self.FontStyleButton:ResetFontStyle("B13", localize("前往"))
        end
    end
end

function ActivityFashionPreheatingCell:PlayFadeInAnim(index)
    CfUtils.PlayDelayShowAnimation(self.AnimRoot, index +1)
end

function ActivityFashionPreheatingCell:PlayInitAnim()
    if not isNull(self.AnimRoot) then
        CfUtils.PlayAnimation(self.AnimRoot, "UI_Common_List_Cell_Idle")
    end
end


return ActivityFashionPreheatingCell
 
 